mapper.select:
SELECT

FROM  MOD_ECL_RESULT_PROCESS A
WHERE  to_char(A.DEC_DATE,'yyyy-MM-dd') = to_char(#{plateDate,jdbcType = DATE},'yyyy-MM-dd')
AND A.PROCESS= #{process}


	AND PS IN ('T01','T35')
	AND A.EAD != 0 


	AND (A.ASSET_ID IN


			null) OR ASSET_ID in (

		#{item}

	)

		select
			A.SEQNO as seqNo,
			#{configType} as configType,
			#{yearNum,jdbcType=DECIMAL} as yearNum,
			#{yearNum,jdbcType=DECIMAL} as yearStr,
			A.FORWARD_YEAR_PD as forwardYearPd
		from  MOD_GRADE_PD_CONFIG A
		where
        A.GRADE_RESULT=#{gradeResult,jdbcType=VARCHAR}
		AND A.VOUCH_YEAR =
		      (select max(B.vouch_year)  from MOD_GRADE_PD_CONFIG B
		       where B.vouch_year  <= #{yearNum,jdbcType=DECIMAL}
		        and B.PD_CONFIG_TYPE = #{pdConfigType}
		    	)
		AND A.PD_CONFIG_TYPE = #{pdConfigType}
		AND ROWNUM=1

		SELECT COUNT(1)
	      FROM MOD_CONFIG_USEAGE A
       WHERE A.CONFIG_SEQNO =#{configSeqNo,jdbcType=VARCHAR}
          AND A.CONFIG_TYPE =#{configType,jdbcType=VARCHAR}
